// `ember codegen`: ember/_generated/{api,dataModel,server,errors,types}.{js,d.ts} + api.d.ts.map + manifest.json
// (docs/design/dx.md §3.5).
//
// - api.d.ts, dataModel.d.ts, errors.d.ts and types.d.ts are static (PLAN §11): args come from the `args` validators,
//   return types from `returns` validators or the TypeScript compiler, errors from `errors:` and from the handlers.
//   They import only each other, so a client type-checks without loading server code. The return types are computed
//   to a fixed point (a function returning another's result needs that one's type first), JSDoc and `@throws` /
//   `@source` tags go on every function, and api.d.ts.map sends Go to Definition to the handler.
// - server.d.ts is for server code only: typed builders over `DataModelFromSchema<typeof schema>`.
// - manifest.json: schema manifest + function list (name, type, visibility, arg/return shapes, errors) + crons.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import type { ObjectShape, Shape } from "@freecorps/ember-values";
import type { AuthTableDescriptor } from "@freecorps/ember-auth";
import { composeApp, isAppDefinition, splitFunctionName, type HttpRouter, type SchemaDefinition, type TypedRouteSpec } from "@freecorps/ember-server";
import { authModeOf, loadProjectCode, type LoadedProject } from "../build.ts";
import type { Project } from "../config.ts";
import { discover } from "../modules.ts";
import { aiGuidelines } from "./ai.ts";
import { relativeTo, TypeOracle, type FunctionTypeInfo, type NamedType } from "./returnTypes.ts";
import { propKey, shapeToTs } from "./shapeToTs.ts";

const HEADER = "/* eslint-disable */\n// Generated by `ember codegen`. Do not edit.\n";
const IS_FUNCTION = Symbol.for("ember.function");

export interface FunctionManifest {
  name: string;
  type: "query" | "mutation" | "action" | "httpAction";
  visibility: "public" | "internal";
  /** Re-checks the session in the Auth DO on every call (PLAN §9). */
  sensitive?: true;
  /** Install path of the component this function belongs to (PLAN §12); never client-callable. */
  component?: string;
  args?: ObjectShape;
  returns?: Shape;
  /** Application errors it may throw: declared (`errors:`) and inferred from the handler. */
  errors?: string[];
  /** Whether `errors` is a declared contract (`errors: [...]` in the definition). */
  errorsDeclared?: true;
  /** The shard kind it runs in (`shard:`); `fromArg`: the argument clients route by. */
  shard?: { kind: string; fromArg?: string };
}

/** One code of `defineErrors` (the payload shape, null when it carries none). */
export interface ErrorManifest {
  code: string;
  data: Shape | null;
  message?: string;
  /** HTTP status of typed routes answering with it. */
  status?: number;
}

export interface EmberManifest {
  formatVersion: 1;
  schema: { version: string; hash: string; tables: Record<string, unknown>; shards: Record<string, unknown> } & Record<string, unknown>;
  functions: FunctionManifest[];
  crons: Array<{ name: string; schedule: string; tz?: string; shard: string; fn: string }>;
  /** Application error codes (`defineErrors`), for clients, OpenAPI and the dashboard. */
  errors?: ErrorManifest[];
  /** Declared env vars (`defineApp({ env })`). */
  env?: Array<{ name: string; optional: boolean }>;
  /** Typed HTTP routes of ember/http.ts (`http.route({ params, query, body, returns, handler })`). */
  routes?: TypedRouteSpec[];
  /** `local`: this project's Auth DO (read-only `auth:*` tables); `remote`: SSO against another project. */
  auth?: { mode: "local"; tables: AuthTableDescriptor[] } | { mode: "remote"; from: string };
}

export interface CodegenResult {
  manifest: EmberManifest;
  /** Files whose content changed (none with `check`). */
  written: string[];
  warnings: string[];
  /** `strict`: what makes the run fail (a warning in normal mode). */
  errors: string[];
  /** `check`: generated files that are missing or out of date. */
  stale: string[];
  /** The contract of each function, as printed in api.d.ts (for `ember types`). */
  contracts: Map<string, string>;
}

export interface CodegenOptions {
  /** Keeps the TypeScript program between runs (`ember dev`). */
  oracle?: TypeOracle;
  /** Write nothing; report the generated files that would change (CI: `ember codegen --check`). */
  check?: boolean;
  /** Fail on `any`/`unknown` return types and on errors a function throws without declaring them. */
  strict?: boolean;
}

/** Writes only when the content changed (keeps editors and tsc watchers quiet). */
function writeIfChanged(dir: string, name: string, text: string, written: string[]) {
  const p = join(dir, name);
  mkdirSync(dirname(p), { recursive: true });
  if (existsSync(p) && readFileSync(p, "utf8") === text) return;
  writeFileSync(p, text);
  written.push(name);
}

const ERROR_FACTORY = Symbol.for("ember.errorFactory");
/**
 * The app's error codes: every `defineErrors` entry its modules export (directly or as `export const errors =
 * defineErrors(...)`), in module order. One code defined twice with different data is refused.
 */
function errorsOf(modules: Record<string, unknown>): ErrorManifest[] {
  const out = new Map<string, ErrorManifest>();
  const add = (x: unknown, where: string) => {
    if (typeof x !== "function" || (x as unknown as Record<symbol, unknown>)[ERROR_FACTORY] !== true) return;
    const f = x as unknown as { code: string; shape: Shape | null; message?: string; status?: number };
    const prev = out.get(f.code);
    if (prev) {
      if (JSON.stringify(prev.data) !== JSON.stringify(f.shape)) throw new Error(`error code ${f.code} is defined twice with different data (ember/${where})`);
      return;
    }
    out.set(f.code, { code: f.code, data: f.shape, ...(f.message ? { message: f.message } : {}), ...(f.status !== undefined ? { status: f.status } : {}) });
  };
  for (const [path, mod] of Object.entries(modules)) {
    for (const x of Object.values((mod ?? {}) as Record<string, unknown>)) {
      add(x, path);
      if (x && typeof x === "object" && !Array.isArray(x)) for (const y of Object.values(x as Record<string, unknown>)) add(y, path);
    }
  }
  return [...out.values()];
}
const MAX_ITERATIONS = 6;

export async function codegen(project: Project, opts: CodegenOptions = {}): Promise<CodegenResult> {
  const out = project.generatedDir;
  const files = discover(project.dir);
  if (!files.schema) throw new Error(`${project.dir}/schema.ts is missing (it must \`export default defineSchema(...)\`)`);
  const warnings: string[] = [];
  const errors: string[] = [];
  const generated = new Map<string, string>();

  // 1. Runtime stubs first: user modules import ./_generated/server and ./_generated/api (evaluated next).
  generated.set("server.js", SERVER_JS);
  generated.set("server.d.ts", serverDts(!!files.appConfig));
  generated.set("api.js", apiJs({}));
  generated.set("dataModel.js", `${HEADER}export {};\n`);
  if (!opts.check) {
    mkdirSync(out, { recursive: true });
    for (const name of ["server.js", "server.d.ts", "dataModel.js"]) writeIfChanged(out, name, generated.get(name)!, []);
    // api.js carries the routing table: keep the current one while the code is evaluated (the final write updates it).
    if (!existsSync(join(out, "api.js"))) writeFileSync(join(out, "api.js"), generated.get("api.js")!);
  }

  // 2. Evaluate the code: validates the schema and yields the function list and the error codes.
  const loaded = await loadProjectCode(project, files, opts.check ? new Map([...generated].map(([k, v]) => [join(out, k), v])) : undefined);
  const manifest = buildManifest(loaded);
  const errorCodes = errorsOf(loaded.modules);
  if (errorCodes.length) manifest.errors = errorCodes;
  const auth = await authManifest(project, loaded, Object.keys(manifest.schema.tables));
  if (auth) manifest.auth = auth;

  // 3. Static data model and errors.
  generated.set("dataModel.d.ts", dataModelDts(manifest));
  generated.set("errors.js", errorsJs(errorCodes));
  generated.set("validators.js", validatorsJs(manifest));
  generated.set("http.js", HTTP_JS);
  generated.set("http.d.ts", httpDts(manifest));
  generated.set("validators.d.ts", VALIDATORS_DTS);
  generated.set("api.js", apiJs(Object.fromEntries(manifest.functions.filter((f) => f.shard && !f.name.startsWith("@")).map((f) => [f.name, f.shard!]))));
  const shardKinds = (manifest.schema.shards ?? {}) as Record<string, { key: Shape }>;
  generated.set("shards.js", shardsJs(shardKinds));
  generated.set("shards.d.ts", shardsDts(shardKinds));
  generated.set("errors.d.ts", errorsDts(errorCodes));

  // 4. Function types to a fixed point: each iteration type-checks the modules against the previous api.d.ts.
  const oracle = opts.oracle ?? new TypeOracle();
  const wanted = new Set(manifest.functions.filter((f) => f.type !== "httpAction" && f.component === undefined && !f.name.startsWith("@")).map((f) => f.name));
  const inferReturns = new Set(manifest.functions.filter((f) => wanted.has(f.name) && !f.returns).map((f) => f.name));
  const onDisk = (name: string) => (existsSync(join(out, name)) ? readFileSync(join(out, name), "utf8") : undefined);
  const known = new Set(errorCodes.map((e) => e.code));
  const disk = onDisk("api.d.ts");
  // The api on disk is usually current (one pass converges): only then is the first pass worth its diagnostics.
  const fromDisk = !!disk && disk.includes("export type Mutation<Args, Returns, Errors extends ErrorSpec>");
  let api = fromDisk ? disk! : apiDts(manifest, new Map(), known, out).text;
  let types = onDisk("types.d.ts") ?? typesDts([]);
  let infos = new Map<string, FunctionTypeInfo>();
  let named: NamedType[] = [];
  let diagnostics: string[] = [];
  let converged = false;
  for (let i = 0; i < MAX_ITERATIONS; i++) {
    const virtualFiles = new Map<string, string>([
      [join(out, "api.d.ts"), api],
      [join(out, "types.d.ts"), types],
      [join(out, "errors.d.ts"), generated.get("errors.d.ts")!],
      [join(out, "dataModel.d.ts"), generated.get("dataModel.d.ts")!],
      [join(out, "server.d.ts"), generated.get("server.d.ts")!],
    ]);
    // The last pass needs diagnostics; a pass from the stub api never converges, so it skips them (unless it is the
    // only one: an app without functions).
    let withDiagnostics = i > 0 || fromDisk || wanted.size === 0;
    let r = oracle.infer({ modules: files.modules, wanted, inferReturns, virtualFiles, generatedDir: out, projectDir: project.dir, diagnostics: withDiagnostics });
    if (!withDiagnostics && apiDts(withInferredErrors(manifest, r.functions, known), r.functions, known, out, r.named).text === api && typesDts(r.named) === types) {
      // Converged on the first pass after all (every result has a validator): this pass is the last, so check it.
      withDiagnostics = true;
      r = oracle.infer({ modules: files.modules, wanted, inferReturns, virtualFiles, generatedDir: out, projectDir: project.dir, diagnostics: true });
    }
    infos = r.functions;
    named = r.named;
    diagnostics = r.diagnostics;
    const nextApi = apiDts(withInferredErrors(manifest, infos, known), infos, known, out, named).text;
    const nextTypes = typesDts(named);
    if (nextApi === api && nextTypes === types) {
      converged = true;
      break;
    }
    api = nextApi;
    types = nextTypes;
  }
  if (!converged) warnings.push(`return types did not settle after ${MAX_ITERATIONS} passes (functions returning each other's results?): add \`returns:\` validators`);
  for (const d of diagnostics) warnings.push(d);

  // Final errors per function (declared ∪ inferred), with the contract checks.
  for (const f of manifest.functions) {
    const info = infos.get(f.name);
    if (!info) continue;
    const declared = f.errors;
    const inferred = info.errors.filter((c) => known.has(c));
    const where = info.source ? ` (${relative(project.root, info.source.file)}:${info.source.line + 1})` : "";
    if (f.errorsDeclared) {
      const missing = inferred.filter((c) => !declared!.includes(c));
      for (const c of missing) {
        const msg = `${f.name} may throw ${c}${where} but does not declare it in \`errors\``;
        (opts.strict ? errors : warnings).push(msg);
      }
      f.errors = [...new Set([...declared!, ...inferred])].sort();
    } else {
      if (inferred.length) f.errors = inferred;
      if (opts.strict && inferred.length && f.visibility === "public") errors.push(`${f.name} throws ${inferred.join(", ")}${where}: declare them with \`errors: [...]\` (strict mode)`);
    }
    if (info.problem) {
      const msg = `${f.name}: return type ${info.problem}${where}; add a \`returns:\` validator or type the value`;
      (opts.strict ? errors : warnings).push(msg);
    }
  }
  const rendered = apiDts(manifest, infos, known, out, named);
  generated.set("api.d.ts", rendered.text);
  generated.set("api.d.ts.map", rendered.map);
  generated.set("types.d.ts", typesDts(named));
  generated.set("manifest.json", JSON.stringify(manifest, null, 2) + "\n");
  generated.set("ai/guidelines.md", aiGuidelines(manifest, rendered.contracts));

  // 5. Write (or compare).
  const written: string[] = [];
  const stale: string[] = [];
  for (const [name, text] of generated) {
    if (opts.check) {
      if (onDisk(name) !== text) stale.push(name);
    } else writeIfChanged(out, name, text, written);
  }
  return { manifest, written, warnings, errors, stale, contracts: rendered.contracts };
}

export function buildManifest(loaded: LoadedProject): EmberManifest {
  const schema = loaded.schema as { manifest?: EmberManifest["schema"] } | undefined;
  if (!schema?.manifest || typeof schema.manifest.version !== "string")
    throw new Error("schema.ts must `export default defineSchema(...)` from @freecorps/ember-server");
  if (loaded.app !== undefined && !isAppDefinition(loaded.app)) {
    throw new Error("ember/ember.config.ts must `export default defineApp()...` from @freecorps/ember-server");
  }
  if (loaded.http !== undefined && !Array.isArray((loaded.http as HttpRouter | null)?.routes)) {
    throw new Error("ember/http.ts must `export default httpRouter()...` from @freecorps/ember-server");
  }
  // Components (PLAN §12): the manifest carries the composed schema (component tables under `<install>$<table>`)
  // and every component function (`@<install>/<module>:<fn>`), the same composition the Worker runs.
  const composed = composeApp({
    schema: loaded.schema as SchemaDefinition<any, any>,
    functions: loaded.modules,
    app: (loaded.app as Parameters<typeof composeApp>[0]["app"]) ?? null,
    http: (loaded.http as HttpRouter | undefined) ?? null,
  });
  const functions: FunctionManifest[] = [];
  for (const [name, x] of Object.entries(composed.functions)) {
    if (!x || typeof x !== "object" || (x as unknown as Record<symbol, unknown>)[IS_FUNCTION] !== true) continue;
    const fn = x as unknown as { type: FunctionManifest["type"]; visibility?: FunctionManifest["visibility"]; args?: ObjectShape; returns?: Shape; sensitive?: true; errors?: Array<{ code: string }>; declaresErrors?: true; shard?: { kind: string; fromArg?: string } };
    const entry: FunctionManifest = { name, type: fn.type, visibility: fn.visibility ?? "public" };
    if (name.startsWith("@")) entry.component = splitFunctionName(name).path.join("/");
    if (fn.sensitive) entry.sensitive = true;
    if (fn.args) entry.args = fn.args;
    if (fn.returns) entry.returns = fn.returns;
    if (fn.errors?.length || fn.declaresErrors) entry.errors = [...new Set((fn.errors ?? []).map((e) => e.code))].sort();
    if (fn.declaresErrors) entry.errorsDeclared = true;
    if (fn.shard) {
      const shards = (composed.schema.manifest as { shards?: Record<string, { key: Shape }> }).shards ?? {};
      const key = shards[fn.shard.kind]?.key ?? (fn.shard.kind === "global" ? { kind: "string" } : undefined);
      if (!key) throw new Error(`${name}: shard "${fn.shard.kind}" is not in defineSchema({ shards }) (known: ${["global", ...Object.keys(shards)].join(", ")})`);
      if (fn.shard.fromArg !== undefined) {
        const arg = fn.args?.fields[fn.shard.fromArg]?.shape;
        const fits = arg && (JSON.stringify(arg) === JSON.stringify(key) || (key.kind === "string" && (arg.kind === "string" || arg.kind === "id")));
        if (!fits) throw new Error(`${name}: argument ${fn.shard.fromArg} does not match the "${fn.shard.kind}" shard key (${shapeToTs(key)})`);
      }
      entry.shard = fn.shard.fromArg === undefined ? { kind: fn.shard.kind } : { kind: fn.shard.kind, fromArg: fn.shard.fromArg };
    }
    functions.push(entry);
  }
  functions.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  const names = new Set(functions.map((f) => f.name));
  // Component crons (hooks) are composed with absolute function names; they run like the app's.
  const crons = [...loaded.crons, ...composed.crons].map((c, i) => {
    const cron = c as Record<string | symbol, unknown>;
    const fnRef = cron.fn as unknown;
    const fn = typeof fnRef === "string" ? fnRef : (fnRef as Record<symbol, unknown> | undefined)?.[Symbol.for("ember.functionName")];
    if (typeof cron.name !== "string" || typeof cron.schedule !== "string" || typeof cron.shard !== "string" || typeof fn !== "string")
      throw new Error(`crons.ts: entry ${i} needs { name, schedule, shard, fn }`);
    if (!names.has(fn)) throw new Error(`crons.ts: "${cron.name}" runs unknown function "${fn}"`);
    return { name: cron.name, schedule: cron.schedule, shard: cron.shard, fn, ...(typeof cron.tz === "string" ? { tz: cron.tz } : {}) };
  });
  const env = Object.entries(((loaded.app as { env?: Record<string, { isOptional: string }> } | undefined)?.env ?? {})).map(([name, val]) => ({ name, optional: val.isOptional === "optional" }));
  const routes = ((loaded.http as HttpRouter | undefined)?.routes ?? []).flatMap((r) => (r.typed ? [r.typed] : []));
  return { formatVersion: 1, schema: composed.schema.manifest as unknown as EmberManifest["schema"], functions, crons, ...(env.length ? { env } : {}), ...(routes.length ? { routes } : {}) };
}

/**
 * Auth part of the manifest (PLAN §9): with `ember/auth.config.ts`, the tables the Auth DO will create (from
 * `getAuthTables`), and a check that no user table takes a reserved auth name.
 */
async function authManifest(project: Project, loaded: LoadedProject, userTables: string[]): Promise<EmberManifest["auth"] | undefined> {
  const mode = authModeOf(project, loaded.files);
  if (!mode) return undefined;
  if (mode.kind === "remote") return { mode: "remote", from: mode.from };
  const { assertNoReservedTables, authTablesManifest, isEmberAuthConfig } = await import("@freecorps/ember-auth");
  const cfg = loaded.authConfig;
  if (!isEmberAuthConfig(cfg)) throw new Error("ember/auth.config.ts must `export default defineAuth({...})` from @freecorps/ember-auth");
  assertNoReservedTables(userTables, cfg);
  return { mode: "local", tables: authTablesManifest(cfg, { project: mode.project }) };
}

const authFieldTs = (t: AuthTableDescriptor["fields"][number]["type"]): string => {
  if (typeof t === "object") return t.enum.map((e) => JSON.stringify(e)).join(" | ") || "string";
  switch (t) {
    case "date":
      return "number";
    case "json":
      return "unknown";
    case "string[]":
      return "string[]";
    case "number[]":
      return "number[]";
    default:
      return t;
  }
};

function authDocumentsDts(tables: AuthTableDescriptor[]): string {
  const docs = tables.map((t) => {
    const fields = [`    id: ${t.idType};`];
    for (const f of t.fields) {
      if (f.hidden) continue;
      fields.push(`    ${propKey(f.name)}${f.optional ? "?" : ""}: ${authFieldTs(f.type)}${f.optional ? " | null" : ""};`);
    }
    return `  ${propKey(t.name)}: {\n${fields.join("\n")}\n  };`;
  });
  return `
/**
 * Read-only auth tables of this project's Auth DO (\`auth:<model>\`, from ember/auth.config.ts). Hidden fields
 * (password hashes, tokens, private keys) are not listed; dates are ms since epoch (as \`internal.users.sync\` gets them).
 */
export type AuthDocuments = {
${docs.join("\n")}
};
export type AuthTableNames = keyof AuthDocuments & string;
`;
}

// ------------------------------------------------------------------------------------------------ templates

const SERVER_JS = `${HEADER}export {
  queryGeneric as query,
  internalQueryGeneric as internalQuery,
  mutationGeneric as mutation,
  internalMutationGeneric as internalMutation,
  actionGeneric as action,
  internalActionGeneric as internalAction,
  httpActionGeneric as httpAction,
  anyComponents as components,
} from "@freecorps/ember-server";
`;

const serverDts = (hasApp: boolean) => `${HEADER}// Server-only: typed builders over the schema. Client code should import ./api and ./dataModel instead.
import type {
  ActionBuilder,
  ComponentsApi,
  ActionCtx as GenericActionCtx,
  DataModelFromSchema,
  DatabaseReader as GenericDatabaseReader,
  EnvOf,
  DatabaseWriter as GenericDatabaseWriter,
  HttpActionBuilder,
  MutationBuilder,
  MutationCtx as GenericMutationCtx,
  QueryBuilder,
  QueryCtx as GenericQueryCtx,
} from "@freecorps/ember-server";
import type schema from "../schema";
${hasApp ? 'import type app from "../ember.config";\n' : ""}
export type DataModel = DataModelFromSchema<typeof schema>;
/** Declared env vars (\`defineApp({ env })\` in ember.config.ts), typed in actions' \`ctx.env\`. */
export type Env = ${hasApp ? "EnvOf<typeof app>" : "{}"};
type EnvCtx = { env: Env & Record<string, unknown> };

/**
 * Installed components (ember/ember.config.ts, PLAN §12): \`components.<name>.<module>.<fn>\` references to their
 * public functions, for ctx.runQuery / ctx.runMutation / ctx.runAction and the scheduler. Server code only.
 */
export declare const components: ${hasApp ? "ComponentsApi<typeof app>" : "{}"};

export declare const query: QueryBuilder<DataModel, "public">;
export declare const internalQuery: QueryBuilder<DataModel, "internal">;
export declare const mutation: MutationBuilder<DataModel, "public">;
export declare const internalMutation: MutationBuilder<DataModel, "internal">;
export declare const action: ActionBuilder<"public", DataModel, EnvCtx>;
export declare const internalAction: ActionBuilder<"internal", DataModel, EnvCtx>;
export declare const httpAction: HttpActionBuilder<DataModel, EnvCtx>;

export type QueryCtx = GenericQueryCtx<DataModel>;
export type MutationCtx = GenericMutationCtx<DataModel>;
/** Actions: shard calls, I/O, and the external index searches (ctx.vectorSearch / ctx.aiSearch) typed by schema. */
export type ActionCtx = GenericActionCtx<DataModel> & EnvCtx;
export type DatabaseReader = GenericDatabaseReader<DataModel>;
export type DatabaseWriter = GenericDatabaseWriter<DataModel>;
`;

const apiJs = (shards: Record<string, { kind: string; fromArg?: string }>) => `${HEADER}// \`api.dir.mod.fn\` is a reference to "dir/mod:fn" (same symbol as @freecorps/ember-client and @freecorps/ember-server).
// References of functions declared with \`shard:\` carry their routing (clients send them to the right shard).
const NAME = Symbol.for("ember.functionName");
const SHARD = Symbol.for("ember.functionShard");
const SHARDS = ${JSON.stringify(shards)};
function nameOf(path) {
  if (path.length < 2) throw new Error("Ember: expected api.module.function, got api." + path.join("."));
  return path.slice(0, -1).join("/") + ":" + path[path.length - 1];
}
function ref(path) {
  return new Proxy({}, {
    get(_, prop) {
      if (prop === NAME) return nameOf(path);
      if (prop === SHARD) return path.length < 2 ? undefined : SHARDS[nameOf(path)] ?? null;
      if (typeof prop === "symbol" || prop === "then" || prop === "toJSON") return undefined;
      return ref([...path, prop]);
    },
  });
}
export const api = ref([]);
export const internal = ref([]);
`;

export function dataModelDts(manifest: EmberManifest): string {
  // Component tables (`<install>$<table>`) are not the app's: they stay out of its data model.
  const tables = Object.entries(manifest.schema.tables as Record<string, { document: ObjectShape }>).filter(([name]) => !name.includes("$"));
  const docs = tables.map(([name, t]) => {
    const withSystem: ObjectShape = {
      kind: "object",
      fields: {
        _id: { shape: { kind: "id", table: name }, optional: false },
        _creationTime: { shape: { kind: "number" }, optional: false },
        ...t.document.fields,
      },
    };
    return `  ${propKey(name)}: ${shapeToTs(withSystem, "  ")};`;
  });
  const auth = manifest.auth?.mode === "local" ? manifest.auth.tables : null;
  const docType = auth
    ? `export type Doc<TableName extends TableNames | AuthTableNames> = TableName extends TableNames
  ? Documents[TableName]
  : TableName extends AuthTableNames
    ? AuthDocuments[TableName]
    : never;`
    : "export type Doc<TableName extends TableNames> = Documents[TableName];";
  return `${HEADER}// Static document types (from the schema manifest). No imports: safe for client code.

export type Id<TableName extends string> = string & { readonly __tableName: TableName };
export type FileId = string & { readonly __file: true };

export type Documents = {
${docs.join("\n")}
};
export type TableNames = keyof Documents & string;
${auth ? authDocumentsDts(auth) : ""}${docType}
`;
}

type Fn = { manifest: FunctionManifest; text: string; doc: string[]; source: FunctionTypeInfo["source"] };
type Tree = { fns: Map<string, Fn>; dirs: Map<string, Tree> };
const newTree = (): Tree => ({ fns: new Map(), dirs: new Map() });

/** Lines of the generated file plus, per line, an optional source position for the declaration map. */
class Emitter {
  readonly lines: string[] = [];
  readonly marks: Array<{ line: number; column: number; source: { file: string; line: number; character: number } }> = [];
  push(line: string) {
    this.lines.push(...line.split("\n"));
  }
  mark(column: number, source: Fn["source"]) {
    if (source) this.marks.push({ line: this.lines.length, column, source });
  }
}

function renderTree(e: Emitter, t: Tree, indent: string) {
  const inner = indent + "  ";
  for (const [k, sub] of [...t.dirs].sort(([a], [b]) => (a < b ? -1 : 1))) {
    e.push(`${inner}${propKey(k)}: {`);
    renderTree(e, sub, inner);
    e.push(`${inner}};`);
  }
  for (const [k, fn] of t.fns) {
    if (fn.doc.length) {
      e.push(`${inner}/**`);
      for (const l of fn.doc) e.push(`${inner} *${l ? ` ${l.replace(/\*\//g, "*\\/")}` : ""}`);
      e.push(`${inner} */`);
    }
    e.mark(inner.length, fn.source);
    e.push(`${inner}${propKey(k)}: ${fn.text};`);
  }
}

/** The manifest with each function's errors: declared ∪ inferred (the inferred ones only for known codes). */
function withInferredErrors(manifest: EmberManifest, infos: Map<string, FunctionTypeInfo>, known: Set<string>): EmberManifest {
  return {
    ...manifest,
    functions: manifest.functions.map((f) => {
      const inferred = (infos.get(f.name)?.errors ?? []).filter((c) => known.has(c));
      const all = [...new Set([...(f.errors ?? []), ...inferred])].sort();
      return all.length ? { ...f, errors: all } : f;
    }),
  };
}

// Split so tools scanning this file for a source map comment (Vite) do not take it as its own.
const SOURCE_MAPPING_URL = "//# " + "sourceMappingURL=";

const ALIAS: Record<string, Record<string, string>> = {
  public: { query: "Query", mutation: "Mutation", action: "Action" },
  internal: { query: "InternalQuery", mutation: "InternalMutation", action: "InternalAction" },
};

/** The doc comment of a function in api.d.ts: its JSDoc, then where it runs, what it throws, where it lives. */
function docLines(f: FunctionManifest, info: FunctionTypeInfo | undefined, outDir: string, messages: Map<string, string | undefined>): string[] {
  const lines = [...(info?.doc ?? [])];
  const extra: string[] = [];
  if (f.shard) extra.push(`@shard ${f.shard.kind}${f.shard.fromArg ? ` (key: args.${f.shard.fromArg}, routed automatically)` : ` (pass { shard: "${f.shard.kind}:<key>" })`}`);
  for (const c of f.errors ?? []) {
    const m = messages.get(c);
    extra.push(`@throws {${c}}${m ? ` ${m}` : ""}`);
  }
  if (info?.source) extra.push(`@source ${relative(dirname(dirname(outDir)), info.source.file).split("\\").join("/")}:${info.source.line + 1}`);
  if (extra.length && lines.length) lines.push("");
  return [...lines, ...extra];
}

export function apiDts(
  manifest: EmberManifest,
  infos: Map<string, FunctionTypeInfo>,
  knownErrors: Set<string>,
  outDir: string,
  named: NamedType[] = [],
): { text: string; map: string; contracts: Map<string, string> } {
  const trees = { public: newTree(), internal: newTree() };
  const contracts = new Map<string, string>();
  const messages = new Map((manifest.errors ?? []).map((e) => [e.code, e.message]));
  for (const f of manifest.functions) {
    if (f.type === "httpAction" || f.component !== undefined || f.name.startsWith("@")) continue;
    const [modPath, exp] = f.name.split(":") as [string, string];
    let node = trees[f.visibility];
    for (const part of modPath.split("/")) {
      if (node.fns.has(part)) throw new Error(`api: "${part}" is both a function and a module in ${f.name}`);
      let next = node.dirs.get(part);
      if (!next) node.dirs.set(part, (next = newTree()));
      node = next;
    }
    if (node.dirs.has(exp)) throw new Error(`api: "${exp}" is both a function and a module in ${f.name}`);
    const fnIndent = "  ".repeat(modPath.split("/").length + 1);
    const info = infos.get(f.name);
    const args = f.args ? shapeToTs(f.args, fnIndent) : "{}";
    const ret = f.returns ? shapeToTs(f.returns, fnIndent) : (info?.returns ?? "unknown").split("\n").join("\n" + fnIndent);
    const errs = (f.errors ?? []).filter((c) => knownErrors.has(c));
    const errText = errs.length ? errs.map((c) => `E.${c}`).join(" | ") : "never";
    const onShard = f.shard ? ` & OnShard<${JSON.stringify(f.shard.kind)}${f.shard.fromArg ? `, ${JSON.stringify(f.shard.fromArg)}` : ""}>` : "";
    const text = `${ALIAS[f.visibility]![f.type]}<${args}, ${ret}, ${errText}>${onShard}`;
    contracts.set(f.name, text.replace(new RegExp(`\\n${fnIndent}`, "g"), "\n"));
    node.fns.set(exp, { manifest: f, text, doc: docLines(f, info, outDir, messages), source: info?.source ?? null });
  }
  const e = new Emitter();
  e.push(`${HEADER}// Static function types: args from validators, returns from \`returns\` validators or the TypeScript
// compiler, errors from \`errors:\` and the handlers. Imports only other generated files, so client code never
// type-checks server code. Go to Definition on \`api.x.y\` opens the handler (api.d.ts.map).
import type { Doc, FileId, Id } from "./dataModel";
import type * as E from "./errors";
${named.length ? `import type { ${named.map((n) => n.name).join(", ")} } from "./types";\n` : ""}
/** An application error a function may throw (see ./errors). */
export type ErrorSpec = { readonly code: string; readonly data: unknown };
/** The shard kind a function runs in (\`fromArg\`: the argument holding its key). */
export type ShardSpec = { readonly kind: string; readonly fromArg?: string };

/** Structurally compatible with @freecorps/ember-client's and @freecorps/ember-server's FunctionReference. */
export type FunctionReference<
  Type extends "query" | "mutation" | "action",
  Visibility extends "public" | "internal",
  Args,
  Returns,
  Errors extends ErrorSpec,
> = {
  readonly _type: Type;
  readonly _visibility: Visibility;
  readonly _args: Args;
  readonly _returnType: Returns;
  readonly _errors?: Errors;
};

/** What \`.paginate()\` returns. */
export type PaginationResult<T> = { page: T[]; isDone: boolean; continueCursor: string };

/**
 * Runs in \`<Kind>:<key>\` shards. With \`FromArg\`, the key is that argument and clients route there by themselves;
 * without it, callers name the shard (\`{ shard: "<Kind>:<key>" }\`, see ./shards).
 */
export type OnShard<Kind extends string, FromArg extends string = never> = {
  readonly _shard?: [FromArg] extends [never] ? { readonly kind: Kind } : { readonly kind: Kind; readonly fromArg: FromArg };
};

/** A function: \`Query<Args, Returns, Errors>\` (\`never\`: it throws no application error). */
export type Query<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"query", "public", Args, Returns, Errors>;
export type Mutation<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"mutation", "public", Args, Returns, Errors>;
export type Action<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"action", "public", Args, Returns, Errors>;
export type InternalQuery<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"query", "internal", Args, Returns, Errors>;
export type InternalMutation<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"mutation", "internal", Args, Returns, Errors>;
export type InternalAction<Args, Returns, Errors extends ErrorSpec> = FunctionReference<"action", "internal", Args, Returns, Errors>;

/** Public functions (client-callable). */
export declare const api: {`);
  renderTree(e, trees.public, "");
  e.push(`};

/** Internal functions: callable from other functions, the scheduler and crons only. */
export declare const internal: {`);
  renderTree(e, trees.internal, "");
  e.push(`};

// Keeps the imports used even when no function mentions them.
export type { Doc as _Doc, FileId as _FileId, Id as _Id };
export type _E = E._Errors;
${SOURCE_MAPPING_URL}api.d.ts.map
`);
  const text = e.lines.join("\n");
  return { text, map: sourceMap(e, join(outDir, "api.d.ts")), contracts };
}

// --------------------------------------------------------------------------------------------- source map

const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function vlq(n: number): string {
  let v = n < 0 ? (-n << 1) | 1 : n << 1;
  let out = "";
  do {
    let digit = v & 31;
    v >>>= 5;
    if (v > 0) digit |= 32;
    out += B64[digit];
  } while (v > 0);
  return out;
}

/** A v3 source map with one segment per function name: api.d.ts position → the export in the user's module. */
function sourceMap(e: Emitter, file: string): string {
  const sources: string[] = [];
  const index = new Map<string, number>();
  const byLine = new Map<number, Emitter["marks"][number]>();
  for (const m of e.marks) byLine.set(m.line, m);
  let prevSrc = 0;
  let prevLine = 0;
  let prevCol = 0;
  const lines: string[] = [];
  for (let i = 0; i < e.lines.length; i++) {
    const m = byLine.get(i);
    if (!m) {
      lines.push("");
      continue;
    }
    const src = relativeTo(file, m.source.file);
    let si = index.get(src);
    if (si === undefined) {
      si = sources.length;
      sources.push(src);
      index.set(src, si);
    }
    lines.push(vlq(m.column) + vlq(si - prevSrc) + vlq(m.source.line - prevLine) + vlq(m.source.character - prevCol));
    prevSrc = si;
    prevLine = m.source.line;
    prevCol = m.source.character;
  }
  return JSON.stringify({ version: 3, file: "api.d.ts", sourceRoot: "", sources, names: [], mappings: lines.join(";") }) + "\n";
}

// ------------------------------------------------------------------------------------------- errors, types

export function errorsJs(errors: ErrorManifest[]): string {
  const entries = errors.map((e) => `  ${propKey(e.code)}: ref(${JSON.stringify(e.code)}),`).join("\n");
  return `${HEADER}// The app's error codes (defineErrors), for client code: \`errors.RoomNotFound.is(e)\` or \`isError(e, errors.RoomNotFound)\`.
const ref = (code) => Object.freeze({ code, is: (e) => e != null && typeof e === "object" && e.kind === "app" && e.code === code });
export const errors = Object.freeze({
${entries}
});
`;
}

export function errorsDts(errors: ErrorManifest[]): string {
  const specs = errors.map((e) => {
    const data = e.data ? shapeToTs(e.data, "") : "undefined";
    const doc = e.message ? `/** ${e.message.replace(/\*\//g, "*\\/")} */\n` : "";
    return `${doc}export type ${e.code} = { readonly code: ${JSON.stringify(e.code)}; readonly data: ${data} };`;
  });
  return `${HEADER}// The app's error codes (defineErrors) and their payloads. No server code: safe for clients.
import type { FileId, Id } from "./dataModel";

${specs.join("\n")}${specs.length ? "\n" : ""}
/** Every application error of this app. */
export type _Errors = ${errors.length ? errors.map((e) => e.code).join(" | ") : "never"};

/** \`errors.X\`: its code, and \`is(e)\` (narrows a caught error to this one, with its typed \`data\`). */
export type ErrorRef<S extends { readonly code: string; readonly data: unknown }> = {
  readonly code: S["code"];
  is(e: unknown): e is Error & { readonly kind: "app"; readonly code: S["code"]; readonly data: S["data"] };
  readonly __spec?: S;
};

export declare const errors: {
${errors.map((e) => `  readonly ${propKey(e.code)}: ErrorRef<${e.code}>;`).join("\n")}
};

export type { FileId as _FileId, Id as _Id };
`;
}

const HTTP_JS = `${HEADER}// Typed client of ember/http.ts's typed routes: \`createHttpClient({ url }).request("GET /mailboxes/:id", { params })\`.
import { decodeJson, encodeJson, EmberError } from "@freecorps/ember-client";

export function createHttpClient(options) {
  const base = String(options.url).replace(/\\/$/, "");
  const doFetch = options.fetch ?? ((...a) => globalThis.fetch(...a));
  return {
    async request(route, input = {}) {
      const at = route.indexOf(" ");
      const method = route.slice(0, at);
      const pattern = route.slice(at + 1);
      const path = pattern.replace(/:([A-Za-z_][A-Za-z0-9_]*)/g, (_, k) => {
        if (input.params?.[k] === undefined) throw new EmberError("bad_args", \`\${route}: params.\${k} is required\`);
        return encodeURIComponent(String(input.params[k]));
      });
      const qs = new URLSearchParams();
      for (const [k, val] of Object.entries(input.query ?? {})) {
        if (val === undefined) continue;
        for (const x of Array.isArray(val) ? val : [val]) qs.append(k, String(x));
      }
      const headers = { ...(typeof options.headers === "function" ? await options.headers() : options.headers ?? {}) };
      if (input.body !== undefined) headers["content-type"] = "application/json";
      let res;
      try {
        res = await doFetch(\`\${base}\${path}\${qs.size ? \`?\${qs}\` : ""}\`, { method, headers, ...(input.body !== undefined ? { body: encodeJson(input.body) } : {}) });
      } catch (e) {
        throw new EmberError("network_error", e?.message ?? "network error", undefined, { outcome: "unknown" });
      }
      const text = await res.text();
      let value;
      try {
        value = text ? decodeJson(text) : null;
      } catch {
        throw new EmberError("bad_response", \`HTTP \${res.status}: response is not JSON\`);
      }
      if (res.ok) return value;
      const e = value?.error ?? {};
      throw new EmberError(e.code ?? \`http_\${res.status}\`, e.message ?? \`HTTP \${res.status}\`, e.data, { kind: e.kind === "app" ? "app" : "system", outcome: "rejected" });
    },
  };
}
`;

export function httpDts(manifest: EmberManifest): string {
  const routes = (manifest.routes ?? []).map((r) => {
    const params = Object.keys(r.params.fields).length ? shapeToTs(r.params, "    ") : "{}";
    const query = Object.keys(r.query.fields).length ? shapeToTs(r.query, "    ") : "{}";
    const body = r.body ? shapeToTs(r.body, "    ") : "undefined";
    const returns = r.returns ? shapeToTs(r.returns, "    ") : "unknown";
    const errs = r.errors.length ? r.errors.map((c) => `E.${c}`).join(" | ") : "never";
    const doc = r.description ? `  /** ${r.description.replace(/\*\//g, "*\\/")} */\n` : "";
    return `${doc}  ${JSON.stringify(`${r.method} ${r.path}`)}: {\n    params: ${params};\n    query: ${query};\n    body: ${body};\n    returns: ${returns};\n    errors: ${errs};\n  };`;
  });
  return `${HEADER}// Typed routes of ember/http.ts. No server code: safe for clients (needs @freecorps/ember-client at runtime).
import type { FileId, Id } from "./dataModel";
import type * as E from "./errors";

export type Routes = {
${routes.join("\n")}
};

type Input<R extends Routes[keyof Routes]> = ({} extends R["params"] ? { params?: R["params"] } : { params: R["params"] }) &
  ({} extends R["query"] ? { query?: R["query"] } : { query: R["query"] }) &
  (R["body"] extends undefined ? { body?: undefined } : { body: R["body"] });

export interface HttpClient {
  /** Calls a typed route: \`request("GET /channels/:channel/messages", { params: { channel }, query: { limit: 5 } })\`. */
  request<K extends keyof Routes>(route: K, ...input: {} extends Input<Routes[K]> ? [input?: Input<Routes[K]>] : [input: Input<Routes[K]>]): Promise<Routes[K]["returns"]>;
}

export declare function createHttpClient(options: {
  /** The deployment URL (\`https://app.example.com\`). */
  url: string;
  fetch?: typeof fetch;
  /** Extra headers (e.g. \`authorization\`), or a function returning them. */
  headers?: Record<string, string> | (() => Record<string, string> | Promise<Record<string, string>>);
}): HttpClient;

export type { FileId as _FileId, Id as _Id };
export type _E = E._Errors;
`;
}

/** The args shapes of the public functions, for client-side validation (`new EmberClient({ validate: argShapes })`). */
export function validatorsJs(manifest: EmberManifest): string {
  const shapes = Object.fromEntries(manifest.functions.filter((f) => f.visibility === "public" && f.type !== "httpAction" && !f.name.startsWith("@") && f.args).map((f) => [f.name, f.args]));
  return `${HEADER}// Argument shapes of the public functions: \`new EmberClient({ url, validate: argShapes })\` rejects invalid arguments
// before they leave (and before an offline mutation is queued). Optional: import it only if you use it.
export const argShapes = ${JSON.stringify(shapes)};
`;
}

const VALIDATORS_DTS = `${HEADER}// No imports: safe for clients.

/** Argument shapes of the public functions, by name (for \`new EmberClient({ validate: argShapes })\`). */
export declare const argShapes: Readonly<Record<string, object>>;
`;

export function shardsJs(kinds: Record<string, { key: Shape }>): string {
  const entries = ["global", ...Object.keys(kinds).filter((k) => k !== "global")].map((k) => `  ${propKey(k)}: (key${k === "global" ? ' = "main"' : ""}) => ${JSON.stringify(k + ":")} + String(key),`);
  return `${HEADER}// Shard names by kind: \`shards.org("acme")\` → "org:acme" (for \`{ shard }\` options and \`ctx.onShard\`).
export const shards = Object.freeze({
${entries.join("\n")}
});
`;
}

export function shardsDts(kinds: Record<string, { key: Shape }>): string {
  const lines = [`  /** The single \`global\` shard (tables without a shard kind). */\n  global(key?: string): \`global:\${string}\`;`];
  for (const [k, s] of Object.entries(kinds)) lines.push(`  ${propKey(k)}(key: ${shapeToTs(s.key, "  ")}): \`${k}:\${string}\`;`);
  return `${HEADER}// Shard names by kind (defineSchema({ shards })). No server code: safe for clients.
import type { FileId, Id } from "./dataModel";

export declare const shards: {
${lines.join("\n")}
};

export type ShardKind = ${["global", ...Object.keys(kinds)].map((k) => JSON.stringify(k)).join(" | ")};
export type { FileId as _FileId, Id as _Id };
`;
}

/** Types the app's modules export and its functions return by name. */
export function typesDts(named: NamedType[]): string {
  return `${HEADER}// Types exported by ember/ modules that function results refer to by name. No server code: safe for clients.
import type { Doc, FileId, Id } from "./dataModel";
import type { PaginationResult } from "./api";

${named.map((n) => `export type ${n.name} = ${n.text};`).join("\n\n")}${named.length ? "\n\n" : ""}export type _Types = ${named.length ? named.map((n) => n.name).join(" | ") : "never"};
export type { Doc as _Doc, FileId as _FileId, Id as _Id, PaginationResult as _PaginationResult };
`;
}
